<template><div v-if="open" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4"><div class="w-full max-w-3xl max-h-[92vh] overflow-hidden border border-slate-200 bg-white"><div class="flex items-center justify-between border-b border-slate-200 px-6 py-4"><div><h2 class="text-lg font-semibold text-slate-900">New bank financing</h2><p class="text-xs text-slate-500">Record financing linked to an offplan application.</p></div><button @click="close" class="border border-slate-200 px-3 py-2">×</button></div><form @submit.prevent="submit" class="max-h-[calc(92vh-80px)] overflow-y-auto"><div class="grid gap-4 p-6 md:grid-cols-2"><Field v-for="f in textFields" :key="f" :label="label(f)"><input v-model="form[f]" class="input" :placeholder="label(f)" /></Field><Field label="Loan term months"><input v-model.number="form.loan_term_months" type="number" min="1" class="input"/></Field><Field label="Loan status"><select v-model="form.loan_status" class="input"><option>pending</option><option>approved</option><option>rejected</option><option>active</option><option>completed</option><option>cancelled</option></select></Field><Field label="Approved at"><input v-model="form.approved_at" type="datetime-local" class="input"/></Field><Field label="First payment date"><input v-model="form.first_payment_date" type="date" class="input"/></Field><Field label="Application ID"><input v-model.number="form.application" type="number" min="1" class="input"/></Field></div><div v-if="error" class="mx-6 mb-4 border border-red-200 bg-red-50 p-3 text-sm text-red-700">{{error}}</div><div class="flex justify-end gap-3 border-t p-4"><button type="button" @click="close" class="border px-5 py-2.5">Cancel</button><button :disabled="loading" class="border border-primary bg-primary px-5 py-2.5 font-semibold text-white">{{loading?'Saving…':'Create financing'}}</button></div></form></div></div></template>
<script>import OffplanField from "../offplan property/OffplanField.vue";const blank=()=>({bank_name:"",loan_account_number:"",loan_amount:"",interest_rate:"",loan_term_months:0,monthly_payment:"",loan_status:"pending",approved_at:"",first_payment_date:"",notes:"",application:0});export default{name:"AddOffplanBankFinancing",components:{Field:OffplanField},props:{open:Boolean},data(){return{form:blank(),loading:false,error:"",textFields:["bank_name","loan_account_number","loan_amount","interest_rate","monthly_payment","notes"]}},watch:{open(v){if(v){this.form=blank();this.error=""}}},methods:{label(v){return v.replace(/_/g," ").replace(/\b\w/g,c=>c.toUpperCase())},close(){if(!this.loading)this.$emit("close")},async submit(){this.loading=true;this.error="";try{await this.$apiPost("/post_offplan_bank_financing",{...this.form,loan_term_months:Number(this.form.loan_term_months),application:Number(this.form.application)});this.$emit("saved");this.close()}catch(e){this.error=e?.message||"Unable to create financing."}finally{this.loading=false}}}}};</script><style scoped>.input{width:100%;border:1px solid #cbd5e1;padding:.625rem .75rem;outline:none;background:#fff;font-size:.875rem}.input:focus{border-color:#5f5ffc}</style>